func main() {
	defer tool.Init()()

	// Cleanup old files in the case set of architectures has changed.
	allFiles, err := filepath.Glob(filepath.Join(*outDir, "sys", generated.Glob()))
	if err != nil {
		tool.Failf("failed to glob: %v", err)
	}
	for _, file := range allFiles {
