	oldFiles, err := filepath.Glob(filepath.Join(*outDir, "sys", "*", "gen", "*"))
	if err != nil {
		tool.Failf("failed to glob: %v", err)
	}
	for _, file := range oldFiles {
		os.Remove(file)
	}

